AI_V = '🎬 Видео создано с помощью ИИ'
AI_C = 'Часть изображений создана с помощью ИИ'

REELS = {
 'g2_polnyj_cikl': f"Один подрядчик — весь дом 🏡\n\nЗемляные работы, фундамент, коробка, кровля, окна и благоустройство — одной командой. Вам не нужно искать разные бригады и разбираться, кто за что отвечает.\n\n{CTA}\n\n{AI_V}\n\n{TAGS}",
 'r2_fundament': f"Почему наши фундаменты не трескаются? 🧱\n\nГеотекстиль, щебёночная подушка, трамбовка, утеплитель, армирование в 2 слоя — и 3–4 недели выдержки, прежде чем начинать стены.\n\nСохраните, чтобы показать своему прорабу 📌\n\n📩 Напишите в директ «СМЕТА» — бесплатно посчитаем фундамент под ваш проект.\n📍 Краснодар и Горячий Ключ\n\n#фундамент #плитныйфундамент {TAGS}",
 'g1_bylo_pole_stal_dom': f"Было поле — стал дом 🏡\n\nВот так выглядит путь от пустого участка до готового дома: фундамент, стены из газоблока, кровля, фасад.\n\nА с какого этапа начали бы вы? Пишите в комментариях 👇\n\n{CTA}\n\n{AI_V}\n\n{TAGS}",
 'r1_ot_polya_do_sten': f"От пустого участка до коробки дома — показали все этапы 🏗\n\nОснование, утепление плиты, армирование, заливка, гидроизоляция, первый ряд газоблока и стены. Это наш реальный объект.\n\n{CTA}\n\n{TAGS}",
 'g3_bez_skrytyh_platezhej': f"Боитесь, что стройка выйдет дороже? 💸\n\nВот как мы это исключаем:\n✔️ смета до начала работ — без скрытых платежей\n✔️ договор и поэтапная оплата\n✔️ фотоотчёты с каждого этапа\n✔️ гарантия на работы\n\n{CTA}\n\n{AI_V}\n\n{TAGS}",
 'r3_steny_gazoblok': f"Сколько стоит дом из газоблока в Краснодаре? 🤔\n\nЗависит от проекта, участка и комплектации — поэтому считаем индивидуально и бесплатно. А пока смотрите, как мы кладём стены: гидроизоляция цоколя, первый ряд по уровню, армирование кладки.\n\n📩 Напишите в директ «СМЕТА» — пришлём расчёт под ваш проект.\n📍 Краснодар и Горячий Ключ\n\n{TAGS}",
}
CAR = {
 'c1_etapy': f"Как строится дом под ключ: 7 этапов 🏡\n\nЛистайте и сохраняйте — пригодится, когда начнёте строить.\n\n{CTA}\n\n{AI_C}\n\n{TAGS}",
 'c2_fundament': f"5 правил фундамента, который не треснет 🧱\n\nВсё на фото — с нашего объекта. Сохраните 📌\n\n{CTA}\n\n#фундамент {TAGS}",
 'c3_smeta': f"Из чего складывается смета на дом 📋\n\nРазобрали по статьям, чтобы вы понимали, за что платите.\n\n{CTA}\n\n{AI_C}\n\n{TAGS}",
 'c4_gazoblok': f"Почему мы строим из газоблока 🧱\n\nТёплый, быстрый, ровный и негорючий. Листайте →\n\n{CTA}\n\n{AI_C}\n\n{TAGS}",
 'c5_oshibki': f"5 ошибок при строительстве дома, которые потом стоят дороже всего ⚠️\n\nСохраните и отправьте тому, кто собирается строиться 👇\n\n{CTA}\n\n{AI_C}\n\n{TAGS}",
 'c6_kak_rabotaem': f"Как мы работаем: от заявки до ключей 🔑\n\n5 простых шагов — и вы в своём доме.\n\n{CTA}\n\n{AI_C}\n\n{TAGS}",
}
def car(cid, n=7): return [f'{RAW}carousels/{cid}/{i:02d}.jpg' for i in range(1, n + 1)]
plan = [
 ('2026-11-13 15:10', 'reel', 'g2_polnyj_cikl'), ('2026-11-13 15:10', 'carousel', 'c1_etapy'), ('2026-11-13 19:00', 'story', 's1'),
 ('2026-11-14 10:00', 'story', 's3'), ('2026-11-14 14:00', 'carousel', 'c2_fundament'), ('2026-11-14 19:00', 'reel', 'r2_fundament'),
 ('2026-11-15 10:00', 'story', 's2'), ('2026-11-15 14:00', 'carousel', 'c3_smeta'), ('2026-11-15 19:00', 'reel', 'g1_bylo_pole_stal_dom'),
 ('2026-11-16 10:00', 'story', 's4'), ('2026-11-16 14:00', 'carousel', 'c4_gazoblok'), ('2026-11-16 19:00', 'reel', 'r1_ot_polya_do_sten'),
 ('2026-11-17 10:00', 'story', 's5'), ('2026-11-17 14:00', 'carousel', 'c5_oshibki'), ('2026-11-17 19:00', 'reel', 'g3_bez_skrytyh_platezhej'),
 ('2026-11-18 10:00', 'story', 's6'), ('2026-11-18 14:00', 'carousel', 'c6_kak_rabotaem'), ('2026-11-18 19:00', 'reel', 'r3_steny_gazoblok'),
 ('2026-11-19 10:00', 'story', 's7'),
]
q = []
for n, (when, t, k) in enumerate(plan, 1):
    it = {'n': n, 'when': when, 'type': t, 'title': k}
    if t == 'reel': it.update(video_url=f'{RAW}reels/{k}.mp4', caption=REELS[k])
    elif t == 'carousel': it.update(slides=car(k), caption=CAR[k])
    else: it.update(image_url=f'{RAW}stories/{k}.jpg')
    it['status'] = 'ready'; q.append(it)
json.dump(q, open('/home/claude/filosofiya-reels/ks/queue.json', 'w'), ensure_ascii=False, indent=1)
print(len(q))
